"""Golden serialization test for the vendored terra_sdk.

The literals in GOLDEN were captured (2026-10-29) from the pre-vendoring
branch point: the terra-sdk==4.0.0 wheel (sha256 b9664b97..., see
src/telliot_feeds/_vendor/UPSTREAM.md) plus the layer reporter code at
uv-run@fdb8e73c. There are no other unit tests for the layer signing path,
so this test is what locks the behavior boundary of the vendoring:
aiohttp-free, deterministic ECDSA, amino JSON + betterproto serialization.

Query type used: SpotPrice (eth/USD, a catalog-supported pair),
encoded as abi.encode("SpotPrice") + abi.encode("eth", "usd").
"""
import json



def _ser(o):
    if isinstance(o, bytes):
        return o.hex()
    return str(o)


def _capture():
    from eth_abi import encode as abi_encode

    from telliot_feeds._vendor.terra_sdk.core import Coin
    from telliot_feeds._vendor.terra_sdk.core import Coins
    from telliot_feeds._vendor.terra_sdk.core.sign_doc import SignDoc
    from telliot_feeds._vendor.terra_sdk.core.tx import AuthInfo
    from telliot_feeds._vendor.terra_sdk.core.tx import Fee
    from telliot_feeds._vendor.terra_sdk.core.tx import SignMode
    from telliot_feeds._vendor.terra_sdk.core.tx import Tx
    from telliot_feeds._vendor.terra_sdk.core.tx import TxBody
    from telliot_feeds.reporters.layer.msg_submit_value import MsgSubmitValue
    from telliot_feeds.reporters.layer.msg_tip import MsgTip
    from telliot_feeds.reporters.layer.raw_key import RawKey
    from telliot_feeds.reporters.layer.raw_key import SignOptions

    priv = "1111111111111111111111111111111111111111111111111111111111111111"
    query_data = abi_encode(["string"], ["SpotPrice"]) + abi_encode(
        ["string", "string"], ["eth", "usd"]
    )
    value = "0x000000000000000000000000000000000000000000000000015c8e52840f4c00"

    key = RawKey.from_hex(priv)
    msg_submit = MsgSubmitValue(creator=key.acc_address, query_data=query_data, value=value)
    msg_tip = MsgTip(tipper=key.acc_address, query_data=query_data, amount="500000loya")

    fee = Fee(gas_limit=420000, amount=Coins([Coin("loya", 200000000000000000)]))
    body = TxBody([msg_submit, msg_tip], "golden memo", 0)

    sign_doc = SignDoc(
        chain_id="golden-layer-1", account_number=7, sequence=3,
        auth_info=AuthInfo([], fee), tx_body=body,
    )

    # amino-JSON variant with str payload: raw bytes in amino dicts break
    # json.dumps in terra_sdk itself (pre-existing; production uses DIRECT)
    body_str = TxBody(
        [MsgSubmitValue(creator=key.acc_address, query_data="0xdead", value=value)],
        "golden memo", 0,
    )
    sign_doc_amino = SignDoc(
        chain_id="golden-layer-1", account_number=7, sequence=3,
        auth_info=AuthInfo([], fee), tx_body=body_str,
    )

    out = {
        "acc_address": key.acc_address,
        "msg_submit_to_data": msg_submit.to_data(),
        "msg_submit_to_amino": msg_submit.to_amino(),
        "msg_tip_to_data": msg_tip.to_data(),
        "msg_tip_to_amino": msg_tip.to_amino(),
        "sign_doc_direct_bytes_hex": sign_doc.to_bytes().hex(),
        "sign_doc_amino_json": sign_doc_amino.to_amino_json().decode("utf-8"),
    }

    signed_direct = key.sign_tx(
        Tx(body=body, auth_info=AuthInfo([], fee), signatures=[]),
        SignOptions(account_number=7, sequence=3, sign_mode=SignMode.SIGN_MODE_DIRECT,
                    chain_id="golden-layer-1"),
    )
    out["signed_direct_to_data"] = signed_direct.to_data()
    out["signed_direct_proto_hex"] = bytes(signed_direct.to_proto()).hex()

    signed_amino = key.sign_tx(
        Tx(body=body_str, auth_info=AuthInfo([], fee), signatures=[]),
        SignOptions(account_number=7, sequence=3,
                    sign_mode=SignMode.SIGN_MODE_LEGACY_AMINO_JSON,
                    chain_id="golden-layer-1"),
    )
    out["signed_amino_to_data"] = signed_amino.to_data()
    return out


